def gcomp_ols(df, target_mask, deg=3, include_placebo=False, spline_df=None):
    terms=[]
    if spline_df is not None:
        terms.append(f'bs(D, df={spline_df}, degree=3, include_intercept=False, lower_bound={Dmin}, upper_bound={Dmax})')
    elif deg==1:
        terms.append('D')
    elif deg==2:
        terms.append('D + np.power(D,2)')
    elif deg==3:
        terms.append('D + np.power(D,2) + np.power(D,3)')
    terms += features
    if include_placebo: terms.append('dY_placebo')
    formula='dY ~ ' + ' + '.join(terms)
    mod=smf.ols(formula, data=df).fit()
    d10=df[target_mask].copy(); d10['D']=10.0
    d19=df[target_mask].copy(); d19['D']=19.0
    y10=mod.predict(d10); y19=mod.predict(d19)
